uniform float speed : 0.0 .. 5.0 = 1.0;

void update() {
    state.x.phase += dt * speed;
}

vec3 shade(Led led) {
    vec2 uv = led.uv;
    float phase = fract(state.x.phase + led.s);
    float angle = atan2(uv.y - 0.5, uv.x - 0.5);
    return hsv2rgb(clamp(mod(angle * 6.0 + phase, 1.0), 0.0, 1.0) * 4.0, 1.0, 0.8);
}

uniform float speed : 0.0 .. 5.0 = 1.0;

void update() {
}

vec3 shade(Led led) {
  float phase = fract(led.s - time * speed);
  return vec3(phase, phase, phase);
}

