uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
}
vec3 shade(Led led) {
  vec3 color = vec3(1.0, 1.0, 1.0);
  float phase = fract(led.s - time * speed);
  float tail_alpha = smoothstep(0.5, 1.0, abs(phase - 0.5));
  return mix(color, palette2(tail_alpha), tail_alpha);
}
